test('相关（同组官方）和自定义写法分开显示，点击替换', async ({ page }) => {
  const fern = page.getByTestId('character').nth(1)
  await chip(fern, 'long hair').click()
  const related = inspector(page).getByTestId('related')
  const custom = inspector(page).getByTestId('custom')
  await expect(related.getByTestId('related-chip').first()).toBeVisible()
  await expect(custom.getByTestId('variant-chip')).toHaveCount(2)

  await custom.getByTestId('variant-chip').filter({ hasText: 'long flowing hair' }).getByRole('button').first().click()
  await expect(chip(fern, 'long flowing hair')).toHaveCount(1)
  await expect(custom.getByTestId('variant-base')).toHaveText(/long hair/)
  await custom.getByTestId('variant-input').fill('silky long hair')
  await custom.getByTestId('variant-input').press('Enter')
  await expect(custom.getByTestId('variant-chip')).toHaveCount(3)
  await page.screenshot({ path: `${SHOTS}/variants.png` })
  const variants = custom.getByTestId('variant-chip')
  const order = await variants.allTextContents()
  await custom.getByRole('button', { name: '删除写法 silky long hair', exact: true }).click()
  await expect(variants).toHaveCount(2)
  const removed = page.locator('[data-sonner-toast]').filter({ hasText: '已删除写法「silky long hair」' })
  await removed.getByRole('button', { name: '撤销' }).click()
  await expect(variants).toHaveText(order)
  await custom.getByRole('button', { name: '删除写法 messy long hair', exact: true }).click()
  await expect(variants).toHaveCount(2)
  await page.locator('[data-sonner-toast]').filter({ hasText: '已删除写法「messy long hair」' }).getByRole('button', { name: '撤销' }).click()
  await expect(variants).toHaveText(order)
  await custom.getByTestId('variant-base').click()
  await expect(chip(fern, 'long hair')).toHaveCount(1)

  const first = (await related.getByTestId('related-chip').first().locator('.chip-text').textContent())!
  await related.getByTestId('related-chip').first().click()
  await expect(chip(fern, first)).toHaveCount(1)
})

