  for (const item of ['编辑', '权重', '禁用（不导出）', '移至', '互动前缀', '复制', '查看 wiki', '删除']) {
    await expect(menu.getByRole('menuitem', { name: item })).toBeVisible()
  }
  await menu.getByRole('menuitem', { name: '禁用（不导出）' }).click()
  await expect(smile).toHaveAttribute('data-disabled', '')
  await expect(exportBase(page)).not.toContainText('smile')

  const sky = chip(page, 'blue sky')
  await sky.click({ button: 'right' })
  await page.getByRole('menuitem', { name: '互动前缀' }).hover()
  await page.getByRole('menuitemradio', { name: /source#/ }).click()
