  await expect(page.getByTestId('chip-menu')).toHaveCount(0)
  await expect(page.locator('.chip[data-selected]')).toHaveCount(3)

  const past = Number((await page.getByTestId('history-count').textContent())!.match(/撤销 (\d+)/)![1])
  await chip(page, 'smile').click({ button: 'right' })
  await page.getByTestId('chip-menu-extract').click()
  expect(await sectionNames(page, 'base.prompt')).toEqual(['主体', '新区块', '场景', '画师', '质量'])
  expect(await chipTexts(section(page, '新区块'))).toEqual(['smile', 'cowboy shot', 'outdoors'])
