  expect(Math.abs(more.y + more.height / 2 - (sw.y + sw.height / 2))).toBeLessThan(1.5)
  await expect(scene.getByTestId('section-collapse')).toHaveCount(0)
  await expect(scene.getByTestId('section-mute')).toHaveCount(0)

  await scene.getByTestId('section-more').click()
