test('选中框：区块和 tag 同一套写法（自己的颜色往里描 2px，不外扩、没有光晕），meta 类 chip 上也明显', async ({ page }) => {
  const settled = (l: Locator) => l.evaluate(async (el) => (await Promise.all(el.getAnimations().map((a) => a.finished)), true))
  const style = (l: Locator) => l.evaluate((el) => { const cs = getComputedStyle(el); return { shadow: cs.boxShadow, outline: `${cs.outlineStyle} ${cs.outlineWidth} ${cs.outlineOffset}`, outlineColor: cs.outlineColor, border: cs.borderTopColor, fg: cs.color } })
  const base = (await style(section(page, '质量'))).shadow
  await clickSectionBlank(page, '质量')
  await settled(section(page, '质量'))
  const sel = (await style(section(page, '质量'))).shadow
  expect(sel.endsWith(`, ${base}`)).toBe(true)
  expect(sel.slice(0, -base.length - 2)).toMatch(/^\S+.* 0px 0px 0px 1px inset$/)
  await chip(page, 'high complexity').click()
  const c = chip(page, 'high complexity')
  await settled(c)
  const st = await style(c)
  expect(st.shadow).toBe('none')
  expect(st.outline).toBe('solid 1px -2px')
  expect(st.border).toBe(st.fg)
  expect(st.outlineColor).toBe(st.fg)
  await settled(section(page, '质量'))
  expect((await style(section(page, '质量'))).shadow).toBe(base)
  await section(page, '质量').screenshot({ path: `${SHOTS}/select-meta-chip.png` })
})

