const secInspector = (page: Page) => page.getByTestId('section-inspector')

test('chip 颜色跟区块走：换区块颜色 chip 跟着变；未识别的 tag 保持灰色；12 色可选', async ({ page }) => {
  const sec = section(page, '场景')
  const hue = (loc: Locator) => loc.evaluate((e) => getComputedStyle(e).getPropertyValue('--h').trim())
  const petals = chip(sec, 'petals')
  expect(await hue(petals)).toBe(String((await sec.evaluate((e) => getComputedStyle(e).getPropertyValue('--sh'))).trim()))
  expect(await hue(chip(page, 'mika pikazo'))).not.toBe(await hue(petals))

  await clickSectionBlank(page, '场景')
  await expect(secInspector(page).getByTestId('section-color')).toHaveCount(12)
  await secInspector(page).getByRole('radio', { name: '品红' }).click()
  await expect.poll(() => hue(petals)).toBe('322')

  await petals.locator('.chip-text').dblclick()
  await page.keyboard.press(`${mod}+a`)
  await page.keyboard.type('粉色眼睛睁开')
  await page.keyboard.press('Enter')
  const unknown = chip(sec, '粉色眼睛睁开')
  await expect(unknown).toHaveAttribute('data-cat', 'text')
  expect(await hue(unknown)).not.toBe('322')
  await sec.screenshot({ path: `${SHOTS}/chip-follow-section.png` })
})

