const favRows = (page: Page) => page.getByTestId('tpl-fav').locator('[data-testid=template-row][data-in-favorites]')
const favNames = (page: Page) => favRows(page).getByTestId('template-name').allTextContents()
const favFolders = (page: Page) => page.getByTestId('tpl-fav').locator('[data-testid=folder-row][data-scope=fav]')
const favFolderRow = (page: Page, path: string) => page.getByTestId('tpl-fav').locator(`[data-testid=folder-row][data-path="${path}"]`)
const treeFolderRow = (page: Page, path: string) => page.getByTestId('tpl-tree').locator(`[data-testid=folder-row][data-path="${path}"]`)
const favRootPaths = (page: Page) =>
  page.getByTestId('tpl-fav').locator('[data-testid=folder-row][data-scope=fav]').evaluateAll((els) => els.filter((e) => e.getAttribute('style')?.includes('padding-left: 4px')).map((e) => e.getAttribute('data-path')))
const treeRow = (page: Page, name: string) =>
  page.getByTestId('tpl-tree').getByTestId('template-row').filter({ has: page.getByTestId('template-name').getByText(name, { exact: true }) })
const storedLibrary = (page: Page) => page.evaluate(async () => JSON.parse((await window.__peImport('/src/store/storage.ts')).safeStorage.getItem('pe:library') ?? '{}').state)

test('模板库：多层目录；示例收藏 = 一个文件夹 + 两个模板', async ({ page }) => {
  expect(await favRootPaths(page)).toEqual(['光照'])
  expect(await favNames(page)).toEqual(['柔和逆光', '通用负面'])
  await expect(treeRow(page, '温柔微笑')).toBeVisible()
  await expect(treeFolderRow(page, '光照')).toHaveAttribute('data-fav', '')
  await page.getByTestId('assistant').screenshot({ path: `${SHOTS}/library.png` })
})

test('收藏文件夹和模板：各自独立，同步到目录，不复制数据，刷新后恢复', async ({ page }) => {
  await treeRow(page, '温柔微笑').getByTestId('template-star').click()
  await treeRow(page, '温柔微笑').getByTestId('template-star').click()
  const before = await storedLibrary(page)
  const sectionsBefore = await sectionNames(page, 'base.prompt')

  await treeFolderRow(page, '表情').getByTestId('folder-star').click()
  expect(await favRootPaths(page)).toEqual(['光照', '表情'])
  await expect(treeFolderRow(page, '表情')).toHaveAttribute('data-fav', '')
  await favFolderRow(page, '表情').getByTestId('template-folder').click()
  await expect(favFolderRow(page, '表情/笑')).toBeVisible()
  await expect(favFolderRow(page, '表情/哭')).toBeVisible()
  await favFolderRow(page, '表情/笑').getByTestId('template-folder').click()
  const inFavFolder = page.getByTestId('tpl-fav').locator('[data-testid=template-row]:not([data-in-favorites])')
  await expect(inFavFolder.filter({ hasText: '温柔微笑' })).toBeVisible()
  await expect(inFavFolder.filter({ hasText: '温柔微笑' })).not.toHaveAttribute('data-fav', '')
  expect(await sectionNames(page, 'base.prompt')).toEqual(sectionsBefore)
  await page.getByTestId('assistant').screenshot({ path: `${SHOTS}/library-fav-folder.png` })

  await treeRow(page, '坏笑').getByTestId('template-star').click()
  expect(await favNames(page)).toEqual(['柔和逆光', '通用负面', '坏笑'])
  await expect(inFavFolder.filter({ hasText: '坏笑' })).toHaveAttribute('data-fav', '')

  await page.reload()
  await page.waitForLoadState('networkidle')
  expect(await favRootPaths(page)).toEqual(['光照', '表情'])
  expect(await favNames(page)).toEqual(['柔和逆光', '通用负面', '坏笑'])

  await favFolderRow(page, '表情').first().getByTestId('folder-star').first().click()
  expect(await favRootPaths(page)).toEqual(['光照'])
  expect(await favNames(page)).toEqual(['柔和逆光', '通用负面', '坏笑'])
  await expect(treeFolderRow(page, '表情')).toBeVisible()
  await expect(treeFolderRow(page, '表情')).not.toHaveAttribute('data-fav', '')
  await favRows(page).filter({ hasText: '坏笑' }).click({ button: 'right' })
  await page.getByTestId('template-menu-fav').click()
  expect(await favNames(page)).toEqual(['柔和逆光', '通用负面'])
  expect(await favRootPaths(page)).toEqual(['光照'])
  await expect(treeRow(page, '坏笑')).toHaveCount(1)
  await treeFolderRow(page, '构图').click({ button: 'right' })
  await page.getByTestId('folder-menu-fav').click()
  expect(await favRootPaths(page)).toEqual(['光照', '构图'])

  const after = await storedLibrary(page)
  expect(after.sectionTemplates).toEqual(before.sectionTemplates)
  const byId = new Map(after.sectionTemplates.map((t: { id: string; name: string }) => [t.id, t.name]))
  expect(after.favorites.map((k: string) => (k.startsWith('template:') ? byId.get(k.slice(9)) : k))).toEqual(['folder:光照', '柔和逆光', '通用负面', 'folder:构图'])
})

