const PNG_1PX = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=='
const source = (page: Page) => secInspector(page).getByTestId('section-source').last()
const sources = (page: Page) => secInspector(page).getByTestId('section-source')
const overwriteBtn = (page: Page) => secInspector(page).getByTestId('section-overwrite')
async function nudge(page: Page, sec: Locator, text: string, dy: number) {
  await chip(sec, text).click()
  await page.mouse.wheel(0, dy)
  await page.keyboard.press('Escape')
}
const toastUndo = (page: Page) => page.locator('[data-sonner-toast][data-front="true"]').getByRole('button', { name: '撤销' })
async function openEdit(page: Page, row: Locator) {
  if ((await row.getAttribute('aria-expanded')) !== 'true') await row.click()
  await templateItem(page, row).getByTestId('template-more').click()
  await page.getByTestId('template-more-edit').click()
  await expect(page.getByTestId('template-edit')).toBeVisible()
}
type Tpl = { name: string; note?: string; imageKey?: string; chips: { text: string; weight: number }[] }
const storedTemplates = async (page: Page) => ((await storedLibrary(page))?.sectionTemplates ?? []) as Tpl[]
const storedTemplate = async (page: Page, name: string) => (await storedTemplates(page)).find((t) => t.name === name)

test('从模板插入 = 来自模板；改过 tag 换成「存为新模板 / 覆盖」，改回一样也不回来，Ctrl+Z 撤回去才回来；覆盖（toast 撤销）', async ({ page }) => {
  await folder(page, '构图').click()
  await insertTemplate(page, templateRow(page, '特写'))
  await clickSectionBlank(page, '特写')
  await expect(source(page)).toBeVisible()
  await expect(source(page)).toContainText('来自模板 特写')
  await expect(secInspector(page).getByTestId('section-inspector-save')).toHaveText('保存为区块模板')
  await expect(overwriteBtn(page)).toHaveCount(0)
  const sec = section(page, '特写')
  const weight = chip(sec, 'close-up').getByTestId('chip-weight')
  await nudge(page, sec, 'close-up', -100)
  await expect(weight).toHaveText('1.05')
  await expect(sources(page)).toHaveCount(0)
  await expect(secInspector(page).getByTestId('section-inspector-save')).toHaveText('保存为新模板')
  await expect(overwriteBtn(page)).toHaveText('覆盖原模板')
  await overwriteBtn(page).hover()
  await expect(page.getByRole('tooltip')).toHaveText('用此区块覆盖模板「特写」')
  await page.mouse.move(2, 890)
  await expect(secInspector(page).getByTestId('section-edited-hint')).toHaveText('从模板「特写」插入后已修改')
  await page.waitForTimeout(1000)
  await nudge(page, sec, 'close-up', 100)
  await expect(chip(sec, 'close-up').getByTestId('chip-weight')).toHaveCount(0)
  await expect(overwriteBtn(page)).toBeVisible()
  await expect(sources(page)).toHaveCount(0)
  await page.locator('body').press(`${mod}+z`)
  await page.locator('body').press(`${mod}+z`)
  await expect(source(page)).toBeVisible()
  await expect(overwriteBtn(page)).toHaveCount(0)
  await nudge(page, sec, 'close-up', -100)
  await overwriteBtn(page).click()
  const confirm = page.getByTestId('section-overwrite-confirm')
  await expect(confirm).toBeVisible()
  await expect(confirm.getByTestId('section-overwrite-keep-image')).toHaveCount(0)
  const beforeCancel = await storedTemplates(page)
  await confirm.getByRole('button', { name: '取消', exact: true }).click()
  await expect(confirm).toBeHidden()
  expect(await storedTemplates(page)).toEqual(beforeCancel)
  await overwriteBtn(page).click()
  await expect(confirm).toBeVisible()
  await confirm.getByTestId('section-overwrite-run').click()
  await expect(source(page)).toBeVisible()
  const tplWeight = async () => (await storedTemplate(page, '特写'))?.chips.find((c) => c.text === 'close-up')?.weight
  await expect.poll(tplWeight).toBeCloseTo(1.05)
  await toastUndo(page).click()
  await expect.poll(tplWeight).toBe(1)
  await expect(overwriteBtn(page)).toBeVisible()
  await clickSectionBlank(page, '主体')
  await expect(secInspector(page).getByTestId('section-inspector-name')).toHaveValue('主体')
  await expect(sources(page)).toHaveCount(0)
  await expect(overwriteBtn(page)).toHaveCount(0)
})

