  await expect(page.getByTestId('template-edit')).toBeVisible()
  await page.getByTestId('template-edit-folder').click()
  await page.getByTestId('template-edit-folder-search').fill(' 光照 / 逆光 /')
  await page.getByTestId('template-edit-folder-create').click()
  await expect(page.getByTestId('template-edit-folder-value')).toHaveText('光照/逆光')
  await page.getByTestId('template-edit-note').fill('白天户外用')
  await page.getByTestId('template-edit-file').setInputFiles({ name: 'a.png', mimeType: 'image/png', buffer: Buffer.from(PNG_1PX, 'base64') })
  await expect(page.getByTestId('template-edit-image').locator('img')).toBeVisible()
  await page.getByTestId('template-edit-save').click()
  await expect(page.getByTestId('template-edit')).toHaveCount(0)
  const renamed = favRows(page).filter({ hasText: '逆光' })
