test('Ctrl+K 预览卡不是一高亮就出（停 300ms）', async ({ page }) => {
  await clickSectionBlank(page, '场景')
  await page.evaluate(() => {
    const w = window as unknown as { __t: Record<string, number> }
    w.__t = {}
    new MutationObserver(() => {
      for (const id of ['template-palette-input', 'template-palette-preview'])
        if (!w.__t[id] && document.querySelector(`[data-testid=${id}]`)) w.__t[id] = performance.now()
    }).observe(document.body, { childList: true, subtree: true })
  })
  await page.keyboard.press(`${mod}+k`)
  await page.getByTestId('template-palette-preview').waitFor()
  const t = await page.evaluate(() => (window as unknown as { __t: Record<string, number> }).__t)
  expect(t['template-palette-preview'] - t['template-palette-input']).toBeGreaterThan(250)
})

