  expect(await fs('inspector-literal')).toBeGreaterThan(await fs('inspector-zh'))
  expect(await fs('inspector-zh')).toBeGreaterThan(await fs('inspector-category'))
  const a = (await head.getByTestId('inspector-category').boundingBox())!
  const b = (await head.getByTestId('inspector-source').boundingBox())!
