test('布局：竖条在最左；tab 行横跨助手栏 + 编辑区 + 导出栏；两侧都能收起 / 展开（栏内按钮、窄边）', async ({ page }) => {
  const r = (await page.getByTestId('app-rail').boundingBox())!
  const a = (await page.getByTestId('assistant').boundingBox())!
  const e = (await page.getByTestId('editor-scroll').boundingBox())!
  const x = (await page.getByTestId('export-panel').boundingBox())!
  const t = (await page.getByTestId('tab-row').boundingBox())!
  expect(r.x).toBe(0)
  expect(r.x + r.width).toBeLessThanOrEqual(a.x + 1)
  expect(a.x + a.width).toBeLessThanOrEqual(e.x + 1)
  expect(e.x + e.width).toBeLessThanOrEqual(x.x + 1)
  expect(a.y).toBe(t.y + t.height)
  expect(t.y).toBe(0)
  expect(t.height).toBe(36)
  expect(t.x).toBe(r.x + r.width)
  expect(Math.abs(t.x + t.width - (x.x + x.width))).toBeLessThan(1)
  expect(e.y).toBeGreaterThanOrEqual(t.y + t.height - 1)
  expect(x.y).toBeGreaterThanOrEqual(t.y + t.height - 1)

  const w0 = e.width
  await page.getByTestId('export-collapse').click()
  await expect(page.getByTestId('export-rail')).toBeVisible()
  await page.getByTestId('assist-collapse').click()
  await expect(page.getByTestId('assist-rail')).toBeVisible()
  await expect.poll(async () => (await page.getByTestId('editor-scroll').boundingBox())!.width).toBeGreaterThan(w0 + 500)
  await page.screenshot({ path: `${SHOTS}/both-collapsed.png` })
  await page.getByTestId('export-rail').click()
  await expect(page.getByTestId('export-panel')).toBeVisible()
  await page.getByTestId('assist-rail').click()
  await expect(page.getByTestId('assistant')).toBeVisible()
})

