test('开始页：无搜索词的方向键、读屏语义与 Escape', async ({ page }) => {
  await page.getByTestId('new-tab').click()
  const search = page.getByTestId('start-search')
  await expect(search).toHaveAttribute('role', 'combobox')
  await expect(search).toHaveAttribute('aria-label', '搜索我的文档、最近关闭')
  await expect(page.locator('[data-testid=start-doc][data-active]')).toHaveCount(0)
  await search.press('ArrowDown')
  const first = page.getByTestId('start-doc').first()
  await expect(first).toHaveAttribute('data-active', '')
  await expect(first).toHaveCSS('outline-width', '2px')
  await expect(first).toHaveCSS('outline-offset', '2px')
  await expect.poll(() => first.evaluate(el => {
    const probe = document.createElement('span')
    probe.style.color = 'var(--accent)'
    el.append(probe)
    const accent = getComputedStyle(probe).color
    probe.remove()
    return getComputedStyle(el).outlineColor === accent
  })).toBe(true)
  await expect(search).toHaveAttribute('aria-activedescendant', await first.getAttribute('id') ?? '')
  await search.press('Enter')
  await expect(page.getByTestId('doc-title')).toHaveValue('樱花下的师徒')
  await page.getByTestId('new-tab').click()
  await search.fill('girl')
  await expect(page.getByTestId('start-search-status')).toContainText('个结果')
  await search.press('Escape')
  await expect(search).toHaveValue('')
  await expect(search).toBeFocused()
  await expect(search).not.toHaveAttribute('aria-activedescendant')
  await search.press('Escape')
  await expect(search).not.toBeFocused()
})

test('新标签页：我的文档默认两行、展开收回、搜索全部与窄窗口', async ({ page }) => {
  await page.evaluate(async () => {
    const { useLibrary } = await window.__peImport('/src/store/library.ts')
    const source = useLibrary.getState().docs[0].doc
    useLibrary.setState({ docs: [], recent: [] })
    for (let i = 0; i < 10; i++) useLibrary.getState().saveDoc({ ...source, meta: { ...source.meta, title: `测试文档 ${i}` } })
    useLibrary.getState().pushRecent('最近关闭', source)
  })
  await page.getByTestId('new-tab').click()
  const cards = page.getByTestId('start-doc')
  const toggle = page.getByTestId('start-doc-toggle')
  await expect(cards).toHaveCount(6)
  await expect(toggle).toHaveText('展开全部 10 个')
  await toggle.click()
  await expect(cards).toHaveCount(10)
  await expect(toggle).toHaveText('收回')
  await toggle.click()
  await expect(cards).toHaveCount(6)
  await page.getByTestId('start-search').fill('测试文档')
  await expect(cards).toHaveCount(10)
  await expect(toggle).toHaveCount(0)
  await page.getByTestId('start-search').press('Escape')
  await expect(cards).toHaveCount(6)
  await page.setViewportSize({ width: 800, height: 900 })
  await expect(cards).toHaveCount(4)
  for (let i = 0; i < 5; i++) await page.getByTestId('start-search').press('ArrowDown')
  await expect(page.getByTestId('start-recent')).toHaveAttribute('data-active', '')
  await page.setViewportSize({ width: 1440, height: 900 })
  await expect(cards).toHaveCount(6)
})

