test('老存档（库 v8、list v2）去掉没改过的示例；改过的、自己存的，和指向它们的收藏留着', async ({ page }) => {
  await page.evaluate(async () => {
    // Vite HMR adds ?t= to module URLs; importing the loaded URL avoids a second, uninitialized store instance.
    const live = (path: string) => performance.getEntriesByType('resource').map((e) => e.name).find((n) => new URL(n).pathname === path) ?? path
    const [libPath, listsPath] = [live('/src/store/library.ts'), live('/src/store/lists.ts')]
    const lib = (await import(/* @vite-ignore */ libPath)).useLibrary.getState()
    const lists = (await import(/* @vite-ignore */ listsPath)).useLists.getState().lists
    const state = JSON.parse(JSON.stringify({ ...lib }))
    const smile = state.sectionTemplates.find((t: { name: string }) => t.name === '温柔微笑')
    smile.note = '我改过的备注'
    state.sectionTemplates.push({ id: 'own', name: '我的模板', color: 'sky', folder: '光照', chips: [{ text: 'smile', type: 'tag', weight: 1, disabled: false }], createdAt: 5 })
    state.characterTemplates.find((t: { name: string }) => t.name === '菲伦').note = '我改过的'
    state.favorites = [...state.favorites, `template:${smile.id}`]
    const store = (await window.__peImport('/src/store/storage.ts')).safeStorage
    store.setItem('pe:library', JSON.stringify({ state, version: 8 }))
    store.setItem('pe:lists', JSON.stringify({ state: { lists, norm: 2 }, version: 2 }))
    localStorage.removeItem('pe:seed')
  })
  const before = await storeState(page)
  expect(before.favorites).toEqual(['folder:光照', `template:${before.sectionIds['柔和逆光']}`, `template:${before.sectionIds['通用负面']}`])
  await page.reload()
  await page.waitForLoadState('networkidle')
  const after = await storeState(page)
  expect(after.sections).toEqual(['温柔微笑', '我的模板'])
  expect(after.characters).toEqual(['菲伦'])
  expect(after.docs).toEqual([])
  expect(after.variants).toEqual([])
  expect(after.lists).toEqual([])
  expect(after.favorites).toEqual(['folder:光照', `template:${after.sectionIds['温柔微笑']}`])
  await expect(page.getByTestId('doc-title')).toHaveValue('樱花下的师徒')
  await expect(page.getByTestId('chip').first()).toBeVisible()
})

test('tab 栏：已有新标签页时 + 切过去；拖动排序；放不下先缩窄再横滚，+ 一直看得见', async ({ page }) => {
  const tabs = page.getByTestId('tab')
  await page.getByTestId('new-tab').click()
  await page.getByTestId('tab').nth(0).click()
  await page.getByTestId('new-tab').click()
  await expect(tabs).toHaveCount(2)
  await expect(tabs.nth(1)).toHaveAttribute('data-active', '')

  await page.waitForTimeout(250)
  const a = (await tabs.nth(0).boundingBox())!
  const b = (await tabs.nth(1).boundingBox())!
  await page.mouse.move(a.x + 20, a.y + 15)
  await page.mouse.down()
  await page.mouse.move(a.x + 40, a.y + 15, { steps: 4 })
  await page.mouse.move(b.x + b.width, a.y + 15, { steps: 10 })
  await page.mouse.up()
  await expect(tabs.nth(1).getByTestId('tab-title')).toHaveText('樱花下的师徒')
  await page.waitForTimeout(100) // dnd-kit suppresses the click immediately after a drag, so wait before testing a separate click.

  for (let i = 0; i < 14; i++) {
    await page.getByTestId('new-tab').click()
    await newDoc(page)
  }
  const bar = page.getByTestId('tab-bar')
  expect(await tabs.first().evaluate((e) => Math.round(e.getBoundingClientRect().width))).toBe(96)
  await expect(page.getByTestId('new-tab')).toBeInViewport()
  const before = await bar.evaluate((e) => e.scrollLeft)
  expect(before).toBeGreaterThan(0)
  await bar.hover()
  await page.mouse.wheel(0, -200)
  await expect.poll(() => bar.evaluate((e) => e.scrollLeft)).toBeLessThan(before)
})

test('tab 栏 Chrome 式：竖线在 tab 之间，悬停块和当前卡片两边的线让开、末尾无线；× 一直显示，放不下时只有当前 tab 有 ×；末尾「全部 tab」下拉列出全部、点了切过去', async ({ page }) => {
  for (const t of ['雨夜街头', '单人立绘 · 白底']) {
    await page.getByTestId('new-tab').click()
    await page.getByTestId('start-doc').filter({ hasText: t }).first().locator('button').first().click()
  }
  const tabs = page.getByTestId('tab')
  await tabs.first().click()
  await page.mouse.move(700, 600)
  const sep = (i: number) => page.locator('.tab-item').nth(i).evaluate((e) => getComputedStyle(e, '::after').opacity)
  const card = (i: number) => tabs.nth(i).evaluate((e) => getComputedStyle(e, '::before').opacity)
  const hover = (i: number) => tabs.nth(i).evaluate((e) => getComputedStyle(e, '::after').opacity)
  await expect.poll(() => sep(0)).toBe('0')
  await expect.poll(() => sep(1)).toBe('1')
  await expect.poll(() => sep(2)).toBe('0')
  await expect.poll(() => card(0)).toBe('1')
  for (const i of [1, 2]) await expect.poll(() => card(i)).toBe('0')
  for (let i = 0; i < 3; i++) await expect(tabs.nth(i).getByTestId('close-tab')).toBeVisible()
  await expect.poll(() => tabs.evaluateAll((els) => els.map((e) => e.getBoundingClientRect().width))).toEqual([240, 240, 240])
  await tabs.nth(1).hover()
  for (let i = 0; i < 3; i++) await expect.poll(() => sep(i)).toBe('0')
  await expect.poll(() => hover(1)).toBe('1')
  await expect.poll(() => card(1)).toBe('0')
  await tabs.first().hover()
  await expect.poll(() => hover(0)).toBe('0')
  await expect.poll(() => sep(0)).toBe('0')
  await page.mouse.move(700, 600)

  await page.getByTestId('all-tabs').click()
  const items = page.getByTestId('all-tabs-item')
  await expect(items).toHaveCount(3)
  await expect(items).toHaveText(['樱花下的师徒', '雨夜街头', '单人立绘 · 白底'])
  await expect(items.first()).toHaveAttribute('data-state', 'checked')
  await items.nth(1).click()
  await expect(page.getByTestId('tab').nth(1)).toHaveAttribute('data-active', '')
  await expect(page.getByTestId('doc-title')).toHaveValue('雨夜街头')
  await expect.poll(() => card(0)).toBe('0')
  await expect.poll(() => card(1)).toBe('1')
  await expect.poll(() => card(2)).toBe('0')
  for (let i = 0; i < 3; i++) await expect.poll(() => sep(i)).toBe('0')

  await page.evaluate(() => document.documentElement.classList.add('dark'))
  await tabs.nth(2).hover()
  await expect.poll(() => hover(2)).toBe('1')
  const lightness = async (i: number, pseudo: string) => tabs.nth(i).evaluate((e, pseudo) => {
    const color = getComputedStyle(e, pseudo).backgroundColor
    if (!color.startsWith('oklch(')) throw new Error('Expected an OKLCH tab surface: ' + color)
    return Number(color.match(/oklch\(([^ ]+)/)![1])
  }, pseudo)
  expect(await lightness(2, '::after')).toBeLessThan(await lightness(1, '::before'))
  await page.evaluate(() => document.documentElement.classList.remove('dark'))
  await page.mouse.move(700, 600)

  const row = page.getByTestId('tab-row')
  for (let i = 0; i < 20 && (await row.getAttribute('data-compressed')) === null; i++) {
    await page.getByTestId('new-tab').click()
    await newDoc(page)
    await page.waitForTimeout(250)
  }
  await expect(row).toHaveAttribute('data-compressed', '')
  await expect(tabs.last().getByTestId('close-tab')).toBeVisible()
  await expect(tabs.first()).toHaveAttribute('data-unsaved', '')
  await expect(tabs.first().getByTestId('close-tab')).toBeVisible()
  await tabs.nth(1).hover()
  await expect(tabs.nth(1).getByTestId('close-tab')).toBeHidden()
  await tabs.last().getByTestId('close-tab').click()
  await page.mouse.move(700, 600)
  await expect(row).not.toHaveAttribute('data-compressed')
  await expect(tabs.nth(1).getByTestId('close-tab')).toBeVisible()
})

test('tab 等宽：少量 240，增多缩窄；连续关闭保持宽度，离开和右键关闭重排', async ({ page }) => {
  const tabs = page.getByTestId('tab')
  const widths = () => tabs.evaluateAll((els) => els.map((e) => Math.round(e.getBoundingClientRect().width)))
  for (let i = 0; i < 2; i++) {
    await page.getByTestId('new-tab').click()
    await newDoc(page)
  }
  await expect.poll(widths).toEqual([240, 240, 240])
  for (let i = 0; i < 5; i++) {
    await page.getByTestId('new-tab').click()
    await newDoc(page)
  }
  await page.waitForTimeout(250)
  const initial = (await widths())[0]
  expect(initial).toBeLessThan(240)
  expect(initial).toBeGreaterThanOrEqual(120)
  expect(new Set(await widths()).size).toBe(1)
  const close = (await tabs.nth(1).getByTestId('close-tab').boundingBox())!
  const x = close.x + close.width / 2
  const y = close.y + close.height / 2
  await page.mouse.click(x, y)
  await expect(tabs).toHaveCount(7)
  await page.waitForTimeout(250)
  expect(await widths()).toEqual(Array(7).fill(initial))
  const next = (await tabs.nth(1).getByTestId('close-tab').boundingBox())!
  expect(next.x).toBe(close.x)
  await page.mouse.click(x, y)
  await expect(tabs).toHaveCount(6)
  expect(await widths()).toEqual(Array(6).fill(initial))
  await page.mouse.move(700, 600)
  await expect.poll(async () => (await widths())[0]).toBeGreaterThan(initial)
  await page.waitForTimeout(250)
  const middleWidth = (await widths())[0]
  await tabs.nth(1).click({ button: 'middle' })
  await expect(tabs).toHaveCount(5)
  await page.waitForTimeout(250)
  expect(await widths()).toEqual(Array(5).fill(middleWidth))
  await tabs.nth(1).click({ button: 'right' })
  await page.getByTestId('tab-menu-close').click()
  await expect(tabs).toHaveCount(4)
  await expect.poll(widths).toEqual([240, 240, 240, 240])
})

test('布局：自动右栏随窗口取 40%，手动宽度保持，双击恢复自动', async ({ page }) => {
  const width = () => page.locator('#right-panel').evaluate((el) => Math.round(el.getBoundingClientRect().width))
  for (const [viewport, expected] of [[1920, 630], [1440, 438], [1100, 360], [1920, 630]]) {
    await page.setViewportSize({ width: viewport, height: 900 })
    await expect.poll(width).toBe(expected)
  }
  const edge = (await page.getByTestId('right-resize').boundingBox())!
  await page.mouse.move(edge.x, edge.y + 200)
  await page.mouse.down()
  await page.mouse.move(edge.x + 130, edge.y + 200, { steps: 5 })
  await page.mouse.up()
  await expect.poll(width).toBe(500)
  await page.setViewportSize({ width: 1440, height: 900 })
  await expect.poll(width).toBe(500)
  await page.getByTestId('right-resize').dblclick()
  await expect.poll(width).toBe(438)
  await page.setViewportSize({ width: 1920, height: 900 })
  await expect.poll(width).toBe(630)
})

for (const viewportWidth of [1440, 1100]) {
  test(`切 tab 不闪：${viewportWidth}`, async ({ page }) => {
    await page.setViewportSize({ width: viewportWidth, height: 900 })
    await page.getByTestId('new-tab').click()
    const record = async () => page.getByTestId('tab').first().evaluate((tab) => new Promise<number[][]>((resolve) => {
      const frames: number[][] = []
      const start = performance.now()
      const tick = () => {
        const w = (selector: string) => document.querySelector(selector)?.getBoundingClientRect().width ?? 0
        frames.push([w('.editor-assistant'), w('#editor-panel'), w('#right-panel')])
        if (performance.now() - start < 600) requestAnimationFrame(tick)
        else resolve(frames)
      }
      tab.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, button: 0 }))
      requestAnimationFrame(tick)
    }))
    const check = (frames: number[][]) => {
      const last = frames.at(-1)!
      expect(last[2]).toBe(viewportWidth === 1440 ? 438 : 360)
      expect(last[0]).toBe(296)
      for (const frame of frames) {
        if (frame[2]) expect(Math.abs(frame[2] - last[2])).toBeLessThanOrEqual(1)
        if (frame[0]) expect(frame[0]).toBe(last[0])
      }
    }
    check(await record())
    await page.keyboard.press(`${mod}+d`)
    await expect(page.getByTestId('tab')).toHaveCount(3)
    check(await record())
  })
}

