const artistCard = (page: Page, name: string) => page.getByTestId('artist-card').filter({ has: page.getByTestId('artist-name').getByText(name, { exact: true }) })

/** Cloudflare challenges headless browsers, so real Danbooru images and API responses are unavailable here. */
async function openArtists(page: Page, log?: string[], byPop = false) {
  await routeDanbooru(page, { log })
  if (!byPop) await page.evaluate(async () => (await window.__peImport('/src/store/prefs.ts')).usePrefs.getState().set({ artistSort: { by: 'count', desc: true } }))
  await page.getByTestId('page-artists').click()
  await artistCard(page, byPop ? 'bluefield' : 'dairi').waitFor()
}
const findArtist = async (page: Page, name: string) => {
  await page.getByTestId('artist-search').fill(name)
  await artistCard(page, name).waitFor()
}
const shownCount = async (page: Page) => {
  const count = page.getByTestId('artist-count')
  await expect(count).toHaveText(/[\d,]+ 位/)
  return Number((await count.textContent())!.match(/([\d,]+) 位/)![1].replace(/,/g, ''))
}

