test('画师库：放大查看完整显示在屏幕里，不超过原图分辨率', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 760 })
  await openArtists(page)
  await artistCard(page, 'dairi').click()
  await page.getByTestId('artist-slide').first().click()
  const frame = page.getByTestId('lightbox-frame')
  for (let i = 0; i < 4; i++) {
    await page.waitForTimeout(300)
    const b = (await frame.boundingBox())!
    expect(b.x).toBeGreaterThanOrEqual(0)
    expect(b.y).toBeGreaterThanOrEqual(0)
    expect(b.x + b.width).toBeLessThanOrEqual(1440)
    expect(b.y + b.height).toBeLessThanOrEqual(760)
    for (const img of await frame.locator('img').all()) {
      const ib = (await img.boundingBox())!
      expect(Math.abs(ib.width - b.width)).toBeLessThan(1)
      expect(Math.abs(ib.height - b.height)).toBeLessThan(1)
    }
    await page.keyboard.press('ArrowRight')
  }
})

