test('画师库：排序方式 + 升降序切换，记在偏好里', async ({ page }) => {
  await openArtists(page, undefined, true)
  const names = () => page.getByTestId('artist-name').allTextContents()
  const byPop = await names()
  expect(byPop[0]).toBe('bluefield')
  await expect(page.getByTestId('artist-sort')).toHaveText('代表作人气')
  await expect(page.getByTestId('artist-sort-dir')).toHaveAttribute('aria-label', '人气高的在前')
  await page.getByTestId('artist-sort').click()
  await expect(page.getByTestId('artist-sort-menu').getByRole('menuitemradio')).toHaveText(['作品数', '代表作人气', '好评率', '总人气', '名称'])
  await page.getByTestId('artist-sort-count').click()
  await expect.poll(names).not.toEqual(byPop)
  const byCount = await names()
  expect(byCount[0]).toBe('dairi')
  await page.getByTestId('artist-sort').click()
  await expect(page.getByTestId('artist-sort-added')).toHaveCount(0)
  await page.getByTestId('artist-sort-name').click()
  const byCode = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0)
  await expect.poll(names).not.toEqual(byCount)
  const az = await names()
  await expect(page.getByTestId('artist-sort')).toHaveText('名称')
  await expect(page.getByTestId('artist-sort-dir')).toHaveAttribute('aria-label', 'A → Z')
  expect(az).toEqual([...az].sort(byCode))
  await page.getByTestId('artist-sort-dir').click()
  await expect.poll(names).not.toEqual(az)
  const za = await names()
  expect(za).toEqual([...za].sort(byCode).reverse())
  expect(byCode(za[0], az[az.length - 1])).toBe(1)
  await page.reload()
  await artistCard(page, za[0]).waitFor()
  expect(await names()).toEqual(za)
})

