test('画师库：只给视野里的卡片问 Danbooru；问过的存在本地，刷新后不再问', async ({ page }) => {
  test.setTimeout(60_000)
  const log: string[] = []
  await openArtists(page, log)
  const posts = () => log.filter((u) => u.startsWith('/posts.json'))
  expect(posts(), '第一屏是预存的，不问').toHaveLength(0)
  await page.getByTestId('artist-sort').click()
  await page.getByTestId('artist-sort-name').click()
  await expect.poll(() => posts().length).toBeGreaterThan(5)
  let last = -1
  await expect.poll(() => { const n = posts().length; const same = n === last; last = n; return same }, { intervals: [1300], timeout: 20000 }).toBe(true)
  const visible = await page.getByTestId('artist-card').evaluateAll((cards) => cards.filter((c) => {
    const r = c.getBoundingClientRect()
    return r.bottom > 0 && r.top < innerHeight
  }).length)
  const asked = posts().length
  expect(asked, `问了 ${asked} 个，视野里 ${visible} 张`).toBeLessThanOrEqual(visible)
  const firstScreen = await page.getByTestId('artist-name').allTextContents()
  await page.getByTestId('artist-page-jump').fill('400')
  await page.getByTestId('artist-page-jump').press('Enter')
  await expect(page.getByTestId('artist-pager').locator('[aria-current="page"]')).toHaveText('400')
  await page.waitForTimeout(1500)
  expect(posts().length - asked).toBeLessThanOrEqual(visible)
  const before = posts().length
  await page.reload()
  await artistCard(page, firstScreen[0]).waitFor()
  await page.waitForTimeout(1500)
  const tagOf = (u: string) => new URL('https://x' + u).searchParams.get('tags')!.split(' ')[0]
  const again = posts().slice(before).map(tagOf)
  expect(again.filter((t) => firstScreen.some((n) => n.replace(/ /g, '_') === t)), '刷新后第一屏没再问').toEqual([])
})

test('画师库：翻页——每页 60 位、页码条、跳至第几页，换页回到顶上；换排序 / 搜索回到第 1 页；翻页不往选中的卡片滚', async ({ page }) => {
  await openArtists(page)
  const total = await shownCount(page)
  const pages = Math.ceil(total / 60)
  const pager = page.getByTestId('artist-pager')
  const current = pager.locator('[aria-current="page"]')
  const vp = page.locator('[data-testid="artists-page"] [data-slot="scroll-area-viewport"]').first()
  const scrollTop = () => vp.evaluate((el) => el.scrollTop)
  const pageNames = async () => {
    const seen = new Set<string>()
    await vp.evaluate((el) => el.scrollTo(0, 0))
    for (let i = 0; i < 40; i++) {
      for (const n of await page.getByTestId('artist-name').allTextContents()) seen.add(n)
      const end = await vp.evaluate((el) => el.scrollTop + el.clientHeight >= el.scrollHeight - 2)
      if (end) break
      await vp.evaluate((el) => el.scrollBy(0, 500))
      await page.waitForTimeout(60)
    }
    return seen
  }
  await expect(pager.getByTestId('artist-page')).toHaveText(['1', '2', '3', '4', '5', String(pages)])
  await expect(current).toHaveText('1')
  await expect(page.getByTestId('artist-page-prev')).toBeDisabled()
  const p1 = await pageNames()
  expect(p1.size).toBe(60)
  expect(p1.has('dairi')).toBe(true)
  await page.getByTestId('artist-page-next').click()
  await expect(current).toHaveText('2')
  expect(await scrollTop()).toBe(0)
  await expect(page.getByTestId('artist-card').first()).not.toContainText('dairi')
  const p2 = await pageNames()
  expect(p2.size).toBe(60)
  expect([...p2].filter((n) => p1.has(n))).toEqual([])
  await pager.getByTestId('artist-page').filter({ hasText: /^5$/ }).click()
  await expect(pager.getByTestId('artist-page')).toHaveText(['1', '4', '5', '6', String(pages)])
  await expect(pager.locator('[data-slot="pagination-ellipsis"]')).toHaveCount(2)
  await page.getByTestId('artist-page-jump').fill('99999')
  await page.getByTestId('artist-page-jump').press('Enter')
  await expect(current).toHaveText(String(pages))
  await expect(page.getByTestId('artist-page-next')).toBeDisabled()
  await expect(page.getByTestId('artist-page-jump')).toHaveValue('')
  expect((await pageNames()).size).toBe(total - (pages - 1) * 60)
  await page.getByTestId('artist-sort-dir').click()
  await expect(current).toHaveText('1')
  await page.getByTestId('artist-sort-dir').click()
  await expect(current).toHaveText('1')
  await vp.evaluate((el) => el.scrollTo(0, el.scrollHeight))
  await artistCard(page, [...p1].at(-1)!).click()
  await expect(page.getByTestId('artist-detail')).toBeVisible()
  await page.waitForTimeout(500)
  await page.getByTestId('artist-page-next').click()
  await page.waitForTimeout(500)
  expect(await scrollTop()).toBe(0)
  await page.getByTestId('artist-page-prev').click()
  await expect(current).toHaveText('1')
  await page.waitForTimeout(500)
  expect(await scrollTop(), '翻回选中的卡片那一页也停在顶上').toBe(0)
  await expect(page.getByTestId('artist-detail')).toBeVisible()
  await page.getByTestId('artist-search').fill('ciloranko')
  await artistCard(page, 'ciloranko').waitFor()
  await expect(pager).toHaveCount(0)
  await page.getByTestId('artist-search').fill('')
  await expect(current).toHaveText('1')
})

// Absolutely positioned sr-only text can escape ScrollArea's clipping and enlarge the document unless the viewport is positioned.
test('各页面网页本身不比窗口高：画师库网格滚到底再滚，界面不动', async ({ page }) => {
  const docHeight = () => page.evaluate(() => ({ h: document.scrollingElement!.scrollHeight, top: document.scrollingElement!.scrollTop, inner: innerHeight }))
  await openArtists(page)
  await expect(page.getByTestId('artist-pager')).toBeVisible()
  const vp = page.locator('[data-testid="artists-page"] [data-slot="scroll-area-viewport"]').first()
  await vp.evaluate((el) => (el.scrollTop = el.scrollHeight))
  await page.mouse.move(700, 400)
  for (let i = 0; i < 3; i++) await page.mouse.wheel(0, 200)
  await page.waitForTimeout(300)
  let d = await docHeight()
  expect(d.h).toBe(d.inner)
  expect(d.top).toBe(0)
  await page.getByTestId('artist-page-next').click()
  await page.getByTestId('artist-card').first().click()
  await page.waitForTimeout(300)
  d = await docHeight()
  expect([d.h, d.top]).toEqual([d.inner, 0])
  for (const p of ['page-editor', 'page-discover', 'page-gacha', 'page-library', 'rail-settings']) {
    await page.getByTestId(p).click()
    await page.waitForTimeout(300)
    d = await docHeight()
    expect(d.h, p).toBe(d.inner)
  }
})

test('画师库：Danbooru 回 429 时整个队列先停，过一会儿接着问', async ({ page }) => {
  let first = true
  const times: number[] = []
  await routeDanbooru(page)
  await page.route(/danbooru\.donmai\.us\/posts\.json/, (route) => {
    times.push(Date.now())
    if (first) {
      first = false
      return route.fulfill({ status: 429, headers: { 'access-control-allow-origin': '*' }, body: '{}' })
    }
    return route.fallback()
  })
  await page.getByTestId('page-artists').click()
  await findArtist(page, 'ciloranko')
  await expect(artistCard(page, 'ciloranko').getByTestId('artist-media').locator('img')).toHaveCount(3, { timeout: 10_000 })
  expect(times.length).toBeGreaterThanOrEqual(2)
  expect(times[1] - times[0], '429 以后至少停 2 秒').toBeGreaterThanOrEqual(1900)
  errors = errors.filter((e) => !e.includes('status of 429'))
})

