test('质量标签是下拉 Standard / Light / None；旧存档（开关 + 角色位置）自动升级', async ({ page }) => {
  await openParams(page)
  await expect(page.getByTestId('quality-preset')).toContainText('Standard')
  await page.getByTestId('quality-preset').click()
  await page.getByRole('option', { name: 'None' }).click()
  await expect(page.getByTestId('quality-preset')).toContainText('None')
  await closeParams(page)
  await page.getByTestId('export-tab-json').click()
  const json = JSON.parse((await page.getByTestId('export-json').textContent())!)
  expect(json.tag_hint_qt).toBe(0)
  expect(json.v4_prompt.use_coords).toBe(false)
  await expect(page.getByTestId('character').first()).not.toContainText('位置')

  await page.evaluate(async () => {
    const store = (await window.__peImport('/src/store/storage.ts')).safeStorage
    const key = `pe:doc:${JSON.parse(store.getItem('pe:tabs')!).state.activeId}`
    const doc = JSON.parse(store.getItem(key)!)
    doc.settings = { qualityTags: false, ucPreset: 'heavy', model: 'v5-full' }
    for (const c of doc.characters) delete c.center
    doc.characters[0].position = { x: 0.3, y: 0.5 }
    store.setItem(key, JSON.stringify(doc))
  })
  await page.reload()
  await page.waitForLoadState('networkidle')
  await openParams(page)
  await expect(page.getByTestId('quality-preset')).toContainText('None')
  await expect(page.getByTestId('character').first()).not.toContainText('位置')
  await closeParams(page)
  await page.getByTestId('export-tab-json').click()
  const old = JSON.parse((await page.getByTestId('export-json').textContent())!)
  expect(old.steps).toBe(23)
  expect(old.sampler).toBe('k_euler_ancestral')
  expect(old.v4_prompt.caption.char_captions[0].centers).toEqual([{ x: 0.5, y: 0.5 }])
  expect(errors).toEqual([])
})

test('导出栏：每个框 / 每个角色一张卡片；角色卡头「角色 1 ♀ 芙莉莲」，里面正面 / 负面不缩进；空的压成一行', async ({ page }) => {
  const row = page.getByTestId('export-base.prompt')
  const btn = row.getByTestId('export-copy')
  await page.mouse.move(5, 5)
  await expect(btn).toBeVisible()
  expect(await btn.evaluate((el) => getComputedStyle(el).opacity)).toBe('1')
  await btn.click()
  await expect(btn).toHaveText('已复制')
  expect(await page.evaluate(() => navigator.clipboard.readText())).toContain('2girls, 1boy, multiple girls')
  await expect(btn).toHaveText('复制', { timeout: 3000 })

  const cards = page.getByTestId('export-cards').locator(':scope > *')
  await expect(cards).toHaveCount(5)
  const r0 = (await cards.nth(0).boundingBox())!
  const r1 = (await cards.nth(1).boundingBox())!
  expect(r1.y - (r0.y + r0.height)).toBeGreaterThanOrEqual(6)

  const chars = page.getByTestId('export-char')
  await expect(chars.nth(0).getByTestId('export-char-index')).toHaveText('角色 1')
  await expect(chars.nth(0).getByTestId('export-char-name')).toHaveText('芙莉莲')
  await expect(chars.nth(0).getByTestId('export-label')).toHaveText(['正面', '负面'])
  await expect(chars.nth(0).getByTestId(/export-.*\.uc/).getByTestId('export-empty')).toHaveText('· 空')
  await expect(chars.nth(0).getByTestId(/export-.*\.uc/).getByTestId('export-copy')).toHaveCount(0)
  const outer = (await row.getByTestId('export-label').boundingBox())!.x
  const inner = (await chars.nth(0).getByTestId('export-label').first().boundingBox())!.x
  const head = (await chars.nth(0).getByTestId('export-char-index').boundingBox())!.x
  expect(Math.abs(inner - outer)).toBeLessThan(1)
  expect(Math.abs(head - outer)).toBeLessThan(1)

  await page.getByTestId('add-character').click()
  await page.getByTestId('add-character-other').click()
  await page.getByTestId('character').nth(1).getByTestId('character-enabled').click()
  await expect(chars).toHaveCount(4)
  await expect(chars.nth(1)).toHaveAttribute('data-off', '')
  await expect(chars.nth(1).getByTestId('export-char-note')).toHaveText('未启用 · 不导出')
  await expect(chars.nth(3).getByTestId('export-char-index')).toHaveText('角色 4')
  await expect(chars.nth(3).getByTestId('export-char-name')).toHaveCount(0)
  await expect(chars.nth(3).getByTestId('export-char-note')).toHaveText('正面为空 · 负面为空')

  await page.getByTestId('copy-more').click()
  await page.getByTestId('copy-all').click()
  const all = await page.evaluate(() => navigator.clipboard.readText())
  expect(all).toContain('# 角色 1 芙莉莲 · 正面')
  expect(all).not.toContain('菲伦')
  await page.getByTestId('export-panel').screenshot({ path: `${SHOTS}/export-panel.png` })
})

