  const b = (await ed.boundingBox())!
  await page.mouse.move(5, b.y + 300)
  await page.waitForTimeout(300)
  await expect(bar).toHaveCount(0)
  await page.mouse.move(b.x + 40, b.y + 300)
  await expect(bar).toHaveCount(1)
