test('区块的开关：在头部最右边、和标题行对齐；关 = 不导出，头部别的变淡、开关不变淡；点它不改选中', async ({ page }) => {
  const s = section(page, '画师')
  const sw = s.getByTestId('section-enabled')
  const [wb, sb, hb] = [await sw.boundingBox(), await s.boundingBox(), await s.locator('.section-head').boundingBox()]
  expect(wb!.x + wb!.width).toBeLessThan(sb!.x + sb!.width)
  expect(sb!.x + sb!.width - (wb!.x + wb!.width)).toBeLessThan(16)
  expect(Math.abs(wb!.y + wb!.height / 2 - (hb!.y + hb!.height / 2))).toBeLessThan(2)
  await sw.click()
  await expect(s).toHaveAttribute('data-muted', '')
  await expect(sw).toHaveAttribute('aria-checked', 'false')
  await expect(page.getByTestId('assistant')).toHaveAttribute('data-mode', 'library')
  await expect.poll(() => s.getByTestId('section-name').evaluate((el) => getComputedStyle(el).opacity)).toBe('0.55')
  expect(await sw.evaluate((el) => getComputedStyle(el.parentElement!).opacity)).toBe('1')
  expect(await s.evaluate((el) => getComputedStyle(el).opacity)).toBe('1')
  await expect(s.getByText('未启用 · 不导出')).toBeVisible()
  await expect(exportBase(page)).not.toContainText('kantoku')
  await sw.click()
  await expect(exportBase(page)).toContainText('kantoku')
})

const charNames = (page: Page) => page.getByTestId('character-name').evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value || (e as HTMLInputElement).placeholder))
