const listTags = (page: Page, title: string) =>
  page.evaluate(async (t) => {
    const all = JSON.parse((await window.__peImport('/src/store/storage.ts')).safeStorage.getItem('pe:lists') ?? '{"state":{"lists":[]}}').state.lists as { nodes: { title: string; tags: string[]; children: never[] }[] }[]
    let found: string[] | null = null
    const walk = (ns: { title: string; tags: string[]; children: never[] }[]) => ns.forEach((n) => (n.title === t && !found ? (found = n.tags) : walk(n.children)))
    all.forEach((l) => walk(l.nodes))
    return found as string[] | null
  }, title)

