const gachaPool = (page: Page, name: string) => page.getByTestId('gacha-pool').filter({ has: page.getByTestId('gacha-pool-name').getByText(name, { exact: true }) })
const gachaTags = (page: Page, name: string) => gachaPool(page, name).getByTestId('gacha-draw').evaluateAll((els) => els.map((e) => (e as HTMLElement).dataset.tagKey!.split('|')[1]))
const gachaTemplate = async (page: Page, id: string) => {
  await page.goto('/#/gacha')
  await page.locator(`[data-testid=gacha-template][data-tpl="${id}"]`).click()
  await expect(page.getByTestId('gacha-center')).toHaveAttribute('data-tpl', id)
}

test('抽卡页——场景模板抽好了；Space 抽一组、锁住的不动；选中 tag 按 R 只换它；右键「本次移除」', async ({ page }) => {
  await gachaTemplate(page, 'tpl:scene')
  await expect(page.getByTestId('gacha-pool')).toHaveCount(4)
  await expect(gachaPool(page, '地点').getByTestId('gacha-draw')).toHaveCount(1)
  await gachaPool(page, '地点').getByTestId('gacha-draw').first().click()
  await page.keyboard.press('l')
  await expect(gachaPool(page, '地点').getByTestId('gacha-draw').first()).toHaveAttribute('data-locked', '')
  const kept = (await gachaTags(page, '地点'))[0]
  await page.keyboard.press('Escape')
  await page.keyboard.press('Escape')
  for (let i = 0; i < 4; i++) await page.keyboard.press('Space')
  expect((await gachaTags(page, '地点'))[0]).toBe(kept)
  const camera = await gachaTags(page, '构图镜头')
  const light = (await gachaTags(page, '光'))[0]
  await gachaPool(page, '光').getByTestId('gacha-draw').first().click()
  let changed = false
  for (let i = 0; i < 5 && !changed; i++) {
    await page.keyboard.press('r')
    changed = (await gachaTags(page, '光'))[0] !== light
  }
  expect(changed).toBe(true)
  expect(await gachaTags(page, '构图镜头')).toEqual(camera)
  const victim = (await gachaTags(page, '光'))[0]
  await gachaPool(page, '光').getByTestId('gacha-draw').first().click({ button: 'right' })
  await expect(page.getByTestId('gacha-menu-exclude')).toHaveCount(0)
  await page.getByTestId('gacha-menu-drop').click()
  expect(await gachaTags(page, '光')).not.toContain(victim)
})

