test('画师模板——名单晚到时先空着（Space 也不记成抽过了），到了自动抽上；画师库 ≥1000；存档不存画师名单', async ({ page }) => {
  let release!: () => void
  const gate = new Promise<void>((r) => (release = r))
  await page.route(/artists\/list\.json\.gz$/, async (route) => {
    await gate
    await route.continue()
  })
  await page.goto('/#/gacha')
  await page.evaluate(async () => {
    const store = (await window.__peImport('/src/store/storage.ts')).safeStorage
    const g = JSON.parse(store.getItem('pe:gacha') ?? '{"state":{},"version":5}')
    g.state.activeTemplate = 'tpl:artist'
    store.setItem('pe:gacha', JSON.stringify(g))
  })
  await page.reload()
  await expect(page.getByTestId('gacha-title')).toHaveText('画师')
  await page.keyboard.press('Space')
  await expect(gachaPool(page, '画师').getByTestId('gacha-draw')).toHaveCount(0)
  release()
  await expect(gachaPool(page, '画师').getByTestId('gacha-draw')).toHaveCount(2)
  await expect(gachaPool(page, '画师').getByTestId('gacha-pool-source')).toContainText('画师库 · 代表作人气前 1000 · 1,000 位')
  await gachaPool(page, '画师').getByTestId('gacha-tune-toggle').click()
  await gachaPool(page, '画师').getByTestId('gacha-tune-count-min').getByLabel('最少加一').click()
  const saved = await page.evaluate(async () => (await window.__peImport('/src/store/storage.ts')).safeStorage.getItem('pe:gacha') ?? '')
  expect(saved).toContain('"tpl:artist":{"tpl-artist":{"count":[3,3]}}')
  expect(saved).not.toContain('"dairi"')
})

test('抽法——卡上拖滑条（0.5 → 1，灯黄跟着填），← → 一格 0.25；「默认为 0.5 · 恢复」', async ({ page }) => {
  await gachaTemplate(page, 'tpl:scene')
  const card = gachaPool(page, '地点')
  await card.getByTestId('gacha-tune-toggle').click()
  const input = card.getByTestId('gacha-tune-pop')
  await expect(input).toHaveValue('0.5')
  for (const [typed, expected] of [['0.3', '0.3'], ['-0.5', '−0.5'], ['5', '1']]) {
    await input.fill(typed)
    await input.press('Enter')
    await expect(input).toHaveValue(expected)
  }
  await input.focus()
  await input.press('ArrowDown')
  await expect(input).toHaveValue('0.75')
  await input.press('ArrowUp')
  await expect(input).toHaveValue('1')
  await card.getByTestId('gacha-tune-pop-reset-btn').click()
  await expect(input).toHaveValue('0.5')
  const thumb = card.getByTestId('gacha-tune-pop-slider').getByRole('slider')
  const box = (await card.getByTestId('gacha-tune-pop-slider').boundingBox())!
  const t = (await thumb.boundingBox())!
  await page.mouse.move(t.x + t.width / 2, t.y + t.height / 2)
  await page.mouse.down()
  await page.mouse.move(box.x + box.width * 0.9, t.y + t.height / 2, { steps: 6 })
  await page.mouse.move(box.x + box.width + 30, t.y + t.height / 2, { steps: 6 })
  await page.mouse.up()
  await expect(input).toHaveValue('1')
  await expect(card.getByTestId('gacha-tune-pop-slider-fill')).toHaveAttribute('style', /left: 50%; width: 50%/)
  await expect(card.getByTestId('gacha-tune-pop-reset')).toContainText('默认为 0.5')
  await thumb.focus()
  await page.keyboard.press('ArrowLeft')
  await page.keyboard.press('ArrowLeft')
  await expect(input).toHaveValue('0.5')
  await expect(card.getByTestId('gacha-tune-pop-reset')).not.toHaveAttribute('data-on', '')
  await input.fill('0')
  await input.press('Enter')
  await card.getByTestId('gacha-tune-pop-reset-btn').click()
  await expect(input).toHaveValue('0.5')
})

