const importDialog = (page: Page) => page.getByTestId('import-dialog')
const intake = (page: Page) => page.getByTestId('image-intake')
async function pickImportPrompt(page: Page) {
  await expect(intake(page)).toBeVisible()
  await page.getByTestId('intake-import').click()
}
const toastText = (page: Page) => page.locator('[data-sonner-toast]').allInnerTexts().then((t) => t.join(' | '))
const clickStatusBar = (page: Page) => page.mouse.click(720, 890)
async function openParams(page: Page) {
  await page.getByTestId('params-button').waitFor()
  await page.waitForTimeout(100)
  if (await page.locator('[data-testid=params-panel][data-state=open]').count()) return
  await expect(page.getByTestId('params-panel')).toHaveCount(0)
  await page.getByTestId('params-button').click()
  await expect(page.locator('[data-testid=params-panel][data-state=open]')).toHaveCount(1)
}
async function closeParams(page: Page) {
  if (!(await page.locator('[data-testid=params-panel][data-state=open]').count())) return
  await page.getByTestId('params-button').click()
  await expect(page.getByTestId('params-panel')).toHaveCount(0)
}
async function copyNaiImage(page: Page) {
  const btn = page.getByTestId('copy-nai-image')
  await btn.click()
  await expect(btn).toHaveAttribute('data-done', '')
  await expect(btn).not.toHaveAttribute('data-done', '')
}
async function writeClipboard(page: Page, { image, text }: { image?: 'clip' | 'plain' | 'saved'; text?: string }) {
  await page.evaluate(
    async ({ image, text, png }) => {
      const items: Record<string, Blob> = {}
      if (image === 'clip') items['image/png'] = await (await navigator.clipboard.read())[0].getType('image/png')
      if (image === 'plain') items['image/png'] = new Blob([Uint8Array.from(atob(png), (c) => c.charCodeAt(0))], { type: 'image/png' })
      if (image === 'saved') items['image/png'] = (window as unknown as { __saved: Blob }).__saved
      if (text) items['text/plain'] = new Blob([text], { type: 'text/plain' })
      await navigator.clipboard.write([new ClipboardItem(items)])
    },
    { image, text, png: PNG_1PX },
  )
}

