test('有文字就按文字粘贴（Word 那种文字 + 图也是）；截图（没元数据）问用途时「导入 prompt」置灰；一次复制几个图片文件读第一张', async ({ page }) => {
  await copyNaiImage(page)
  await writeClipboard(page, { image: 'clip', text: 'paper lantern, koi' })
  await clickStatusBar(page)
  await page.keyboard.press(`${mod}+v`)
  await page.waitForTimeout(500)
  await expect(importDialog(page)).toHaveCount(0)
  expect(await toastText(page)).not.toContain('读不到')
  const sec = section(page, '场景')
  const n = await sec.getByTestId('chip').count()
  await sec.getByTestId('tag-input').click()
  await page.keyboard.press(`${mod}+v`)
  await expect(sec.getByTestId('chip')).toHaveCount(n + 2)
  await expect(importDialog(page)).toHaveCount(0)
  await writeClipboard(page, { image: 'plain' })
  await clickStatusBar(page)
  await page.keyboard.press(`${mod}+v`)
  await expect(intake(page)).toBeVisible()
  const disabledImport = page.getByTestId('intake-import')
  await expect(disabledImport).toBeDisabled()
  await expect(disabledImport).toContainText('未读取到图片信息')
  await disabledImport.hover({ force: true })
  await expect(page.getByRole('tooltip')).toHaveText('请使用 NAI 下载的原图，或在 NAI 中点击「复制」')
  await disabledImport.click({ force: true })
  await page.getByTestId('intake-gallery').hover()
  await expect(page.getByRole('tooltip')).toHaveCount(0)
  await expect(page.getByTestId('intake-gallery')).toBeVisible()
  await expect(importDialog(page)).toHaveCount(0)
  await page.keyboard.press('Escape')
  await expect(intake(page)).toHaveCount(0)
  await copyNaiImage(page)
  await page.evaluate(async (png) => {
    const nai = await (await navigator.clipboard.read())[0].getType('image/png')
    const t = new DataTransfer()
    t.items.add(new File([nai], 'a.png', { type: 'image/png' }))
    t.items.add(new File([Uint8Array.from(atob(png), (c) => c.charCodeAt(0))], 'b.png', { type: 'image/png' }))
    document.body.dispatchEvent(new ClipboardEvent('paste', { clipboardData: t, bubbles: true, cancelable: true }))
  }, PNG_1PX)
  await pickImportPrompt(page)
  await expect(importDialog(page)).toBeVisible()
  await expect(importDialog(page)).toContainText('a.png')
  await expect.poll(() => toastText(page)).toContain('一次只能处理一张图片，已读取第一张')
})

