async function openAiMore(page: Page) {
  if (!(await page.getByTestId('ai-chat').isVisible())) {
    if ((await page.getByTestId('rail-ai').getAttribute('aria-pressed')) === 'true') await page.evaluate(async () => (await window.__peImport('/src/store/ui.ts')).useUi.getState().blur())
    else await page.getByTestId('rail-ai').click()
    await expect(page.getByTestId('ai-chat')).toBeVisible()
  }
  await page.getByTestId('ai-chat-more').click()
}
const aiDialog = (page: Page) => page.getByTestId('ai-import')
/** Windows clipboard reads use CRLF, so normalize line endings before matching the JSON block. */
async function copyForAi(page: Page) {
  let text: string
  if ((page.viewportSize()?.width ?? 1440) < 1024) {
    text = await page.evaluate(async () => {
      const t = await window.__peImport('/src/store/tabs.ts')
      const d = await window.__peImport('/src/lib/ai-doc.ts')
      const i = await window.__peImport('/src/store/ai-import.ts')
      return d.aiPromptText(t.getDocStore(t.useTabs.getState().activeId).getState().doc, i.aiOptions())
    })
  } else {
    await openAiMore(page)
    await page.getByTestId('ai-menu-copy').click()
    await expect(page.getByTestId('ai-chat-more')).toHaveClass(/text-lamp-text/)
    await expect(page.locator('[data-slot="dropdown-menu-content"]')).toHaveCount(0)
    text = await page.evaluate(() => navigator.clipboard.readText())
  }
  const doc = JSON.parse([...text.matchAll(/```json\r?\n([\s\S]*?)```/g)][1][1]) as { prompt: { id: string; name: string }[] }
  return { text, sceneId: doc.prompt.find((s) => s.name === '场景')!.id }
}
const aiReply = (o: object) => `改好了：\n\n\`\`\`json\n${JSON.stringify({ $schema: 'pe-doc-ai/1', ...o }, null, 2)}\n\`\`\`\n`
const writeText = (page: Page, t: string) => page.evaluate((t) => navigator.clipboard.writeText(t), t)

test('复制给 AI = 规则 + Schema + 文档；Ctrl+V 粘回答（空白处、tag 输入框里都行）开预览，tag 输入框不拆；普通 prompt 串照旧拆', async ({ page }) => {
  const { text, sceneId } = await copyForAi(page)
  expect(text).toContain('Partial edit (the default): write only the sections, characters and settings you change')
  expect(text).toContain('"$id":"pe-doc-ai/2"')
  await writeText(page, aiReply({ prompt: [{ id: sceneId, text: 'outdoors, sunset, ' }] }))
  await clickStatusBar(page)
  await page.keyboard.press(`${mod}+v`)
  await expect(aiDialog(page)).toBeVisible()
  await expect(aiDialog(page).getByTestId('ai-import-overview')).toContainText('场景：添加 sunset')
  await page.keyboard.press('Escape')
  await expect(aiDialog(page)).toHaveCount(0)
  const input = section(page, '主体').getByTestId('tag-input')
  const before = await chipTexts(section(page, '主体'))
  await input.click()
  await page.keyboard.press(`${mod}+v`)
  await expect(aiDialog(page)).toBeVisible()
  await expect(input).toHaveValue('')
  expect(await chipTexts(section(page, '主体'))).toEqual(before)
  await page.keyboard.press('Escape')
  await expect(aiDialog(page)).toHaveCount(0)
  await writeText(page, 'rim lighting, dutch angle')
  await input.click()
  await page.keyboard.press(`${mod}+v`)
  await expect(chip(section(page, '主体'), 'dutch angle')).toHaveCount(1)
  await expect(aiDialog(page)).toHaveCount(0)
})

