test('把 .json 拖进窗口：提示层写「松开导入 AI 的回答」，松手开预览；不是回答的 .json 只弹 toast', async ({ page }) => {
  const { sceneId } = await copyForAi(page)
  const drop = async (name: string, text: string) => {
    const dt = await page.evaluateHandle(
      ({ name, text }) => {
        const t = new DataTransfer()
        t.items.add(new File([text], name, { type: 'application/json' }))
        return t
      },
      { name, text },
    )
    await page.dispatchEvent('main', 'dragenter', { dataTransfer: dt })
    await page.dispatchEvent('main', 'dragover', { dataTransfer: dt })
    await expect(page.getByTestId('drop-overlay')).toContainText('松开以导入 AI 的回答')
    await page.dispatchEvent('main', 'drop', { dataTransfer: dt })
  }
  await drop('回答.json', JSON.stringify({ $schema: 'pe-doc-ai/1', prompt: [{ id: sceneId, text: 'outdoors, sunset, ' }] }))
  await expect(aiDialog(page)).toBeVisible()
  await page.keyboard.press('Escape')
  await expect(aiDialog(page)).toHaveCount(0)
  await drop('合集.json', JSON.stringify({ $schema: 'pe-gacha/1', name: 'x', pools: [] }))
  await expect.poll(() => toastText(page)).toContain('「合集.json」不是 AI 的回答')
  await expect(aiDialog(page)).toHaveCount(0)
})

