test('很长的 AI 回答（19 处、一行十几个 tag）在 964×800 的窗口里：弹窗不被撑宽，总结行省略号，「应用」看得见、点得到', async ({ page }) => {
  await page.setViewportSize({ width: 964, height: 800 })
  const { sceneId } = await copyForAi(page)
  const many = (stem: string, n: number) => Array.from({ length: n }, (_, i) => `${stem} ${i}`).join(', ')
  const prompt = [{ id: sceneId, text: 'outdoors, ' }, ...Array.from({ length: 9 }, (_, i) => ({ name: `新区块${i}`, text: many(i === 4 ? 'artist:painterxxxx' : 'long tag name', 16) }))]
  const uc = Array.from({ length: 9 }, (_, i) => ({ name: `负面${i}`, text: many('bad thing', 14) }))
  await writeText(page, aiReply({ prompt, uc }))
  await clickStatusBar(page)
  await page.keyboard.press(`${mod}+v`)
  const dlg = aiDialog(page)
  await expect(dlg.getByTestId('ai-change')).toHaveCount(19)
  const box = (await dlg.boundingBox())!
  expect(box.width).toBeLessThanOrEqual(760)
  expect(box.x + box.width).toBeLessThanOrEqual(964)
  expect(await dlg.evaluate((el) => el.scrollWidth - el.clientWidth)).toBe(0)
  const lines = dlg.getByTestId('ai-import-overview').locator('> div.truncate')
  expect(await lines.evaluateAll((els) => els.filter((e) => e.scrollWidth > e.clientWidth + 1).length)).toBeGreaterThan(0)
  const apply = dlg.getByTestId('ai-import-apply')
  await expect(apply).toBeInViewport()
  const a = (await apply.boundingBox())!
  expect(a.x + a.width).toBeLessThanOrEqual(box.x + box.width)
  await apply.click()
  await expect(dlg).toHaveCount(0)
  await expect(section(page, '新区块8')).toHaveCount(1)
})

