test('再次拖入随机角色新建独立框，旧多人区块重抽只剩一人', async ({ page }) => {
  const editor = (await page.getByTestId('editor-scroll').boundingBox())!
  const point = { x: editor.x + editor.width / 2, y: editor.y + 200 }
  const count = await page.getByTestId('character').count()
  await dragRandomRow(page, 'char', point)
  await dragRandomRow(page, 'char', point)
  await expect(page.getByTestId('character')).toHaveCount(count + 2)
  const sections = page.getByTestId('character').getByTestId('section').filter({ has: page.getByTestId('random-head') })
  await expect(sections).toHaveCount(2)
  await page.evaluate(async () => {
    const t = await window.__peImport('/src/store/tabs.ts')
    const store = t.getDocStore(t.useTabs.getState().activeId)
    const doc = structuredClone(store.getState().doc)
    const s = doc.characters.at(-1).prompt[0]
    s.random.count = [2, 2]
    s.chips = [...s.chips, ...s.chips.map((c: { id: string }) => ({ ...c, id: `${c.id}_legacy` }))]
    store.setState({ doc })
  })
  await page.reload()
  const legacy = page.getByTestId('character').last().getByTestId('section').first()
  await expect.poll(() => legacy.getByTestId('chip').count()).toBeGreaterThan(2)
  await legacy.getByTestId('random-reroll').click()
  await expect.poll(() => legacy.getByTestId('chip').count()).toBeLessThanOrEqual(2)
  await expect.poll(() => legacy.getByTestId('chip').count()).toBeGreaterThan(0)
})

test('开始页卡片和最近关闭的悬停过渡', async ({ page }) => {
  for (const theme of ['light', 'dark']) {
    await resetStore(page, { theme })
    await page.reload()
    await page.getByTestId('doc-title').waitFor()
    await page.evaluate(async () => {
      const l = (await window.__peImport('/src/store/library.ts')).useLibrary.getState()
      l.pushRecent(l.docs[0].title, l.docs[0].doc)
    })
    await page.getByTestId('new-tab').click()
    await page.mouse.move(2, 890)
    const card = page.getByTestId('start-doc').first()
    const actions = card.getByTestId('start-doc-rename').locator('..')
    await expect(actions).toHaveCSS('opacity', '0')
    const border = await card.evaluate(e => getComputedStyle(e).borderColor)
    await card.hover()
    await expect(actions).toHaveCSS('opacity', '1')
    await expect.poll(() => card.evaluate(e => getComputedStyle(e).borderColor)).not.toBe(border)
    await expect(card.getByTestId('start-doc-remove')).toBeVisible()
    expect(await actions.evaluate(e => parseFloat(getComputedStyle(e).transitionDuration))).toBeGreaterThanOrEqual(.15)
    await page.mouse.move(2, 890)
    await expect(actions).toHaveCSS('opacity', '0')
    for (const button of [page.getByTestId('start-new'), page.getByTestId('start-recent').first().getByRole('button', { name: /打开/ })]) {
      const bg = await button.evaluate(e => getComputedStyle(e).backgroundColor)
      await button.hover()
      await expect.poll(() => button.evaluate(e => getComputedStyle(e).backgroundColor)).not.toBe(bg)
      expect(await button.evaluate(e => parseFloat(getComputedStyle(e).transitionDuration))).toBeGreaterThanOrEqual(.15)
      await page.mouse.move(2, 890)
      await expect(button).toHaveCSS('background-color', bg)
    }
  }
})

test('画师翻页淡入和收藏筛选重置页码', async ({ page }) => {
  await openArtists(page)
  await page.getByTestId('artist-page-jump').fill('400')
  const [opacity] = await Promise.all([
    page.evaluate(async () => {
      const samples: number[] = []
      const end = performance.now() + 600
      while (performance.now() < end) {
        const grid = document.querySelector('[data-testid=artist-grid]')
        if (grid) samples.push(Number(getComputedStyle(grid).opacity))
        await new Promise(requestAnimationFrame)
      }
      return samples
    }),
    page.getByTestId('artist-page-jump').press('Enter'),
  ])
  await expect(page.getByTestId('artist-pager').locator('[aria-current="page"]')).toHaveText('400')
  expect(opacity.some(v => v > 0 && v < .99)).toBe(true)
  await expect(page.getByTestId('artist-grid')).toHaveCSS('opacity', '1')
  await page.getByTestId('artist-filter-fav').click()
  await expect(page.getByTestId('artist-pager')).toHaveCount(0)
  await page.getByTestId('artist-filter-all').click()
  await expect(page.getByTestId('artist-pager').locator('[aria-current="page"]')).toHaveText('1')
})

