test('输入框右键保留原生菜单', async ({ page }) => {
  const nativeMenu = async (field: Locator) => {
    // React can preventDefault during capture or bubbling; inspect the event in a microtask after both have finished.
    await field.evaluate((el) => {
      document.addEventListener('contextmenu', (event) => {
        queueMicrotask(() => {
          el.setAttribute('data-native-menu', String(!event.defaultPrevented && event.target === el))
        })
      }, { capture: true, once: true })
    })
    await field.scrollIntoViewIfNeeded()
    const before = await field.boundingBox()
    await field.click({ button: 'right' })
    await expect(page.getByRole('menu')).toHaveCount(0)
    await expect(field).toHaveAttribute('data-native-menu', 'true')
    await expect(field).toBeFocused()
    expect(await field.boundingBox()).toEqual(before)
  }
  const scene = section(page, '场景')
  await nativeMenu(scene.getByTestId('tag-input'))
  await scene.getByTestId('tag-input').click()
  await expect(scene.getByTestId('tag-input')).toBeFocused()
  await nativeMenu(scene.getByTestId('tag-input'))
  await scene.getByTestId('section-text-toggle').click()
  await nativeMenu(scene.getByTestId('section-text'))
  await scene.getByTestId('section-name').dblclick()
  await nativeMenu(page.getByTestId('section-name-input'))
  await page.keyboard.press('Escape')
  await nativeMenu(page.getByTestId('character').first().getByTestId('tag-input').first())
})

