test('弹窗遮罩都是 --overlay、不模糊（Ctrl+K 搜索、删除确认、随机区块「添加分类」）', async ({ page }) => {
  const want = await page.evaluate(() => {
    const p = document.createElement('div')
    p.style.background = 'var(--overlay)'
    document.body.append(p)
    const c = getComputedStyle(p).backgroundColor
    p.remove()
    return c
  })
  const overlay = () =>
    page.locator('[data-slot=dialog-overlay], [data-slot=alert-dialog-overlay]').last().evaluate((el) => {
      const s = getComputedStyle(el)
      return { bg: s.backgroundColor, blur: s.backdropFilter }
    })
  await chip(page, 'smile').click()
  await page.keyboard.press(`${mod}+k`)
  await expect(page.getByTestId('template-palette-input')).toBeFocused()
  expect(await overlay()).toEqual({ bg: want, blur: 'none' })
  await page.keyboard.press('Escape')
  await expect(page.getByTestId('template-palette-input')).toHaveCount(0)
  await page.evaluate(async () => (await window.__peImport('/src/store/ui.ts')).useUi.getState().blur())
  await favRows(page).filter({ hasText: '柔和逆光' }).click({ button: 'right' })
  await page.getByTestId('template-menu-delete').click()
  await expect(page.getByTestId('confirm-dialog')).toBeVisible()
  expect(await overlay()).toEqual({ bg: want, blur: 'none' })
  await page.getByTestId('confirm-cancel').click()
  await expect(page.getByTestId('confirm-dialog')).toHaveCount(0)
  await page.locator('[data-testid=lib-folder][data-folder=random]').click()
  await page.locator('[data-testid=random-row][data-kind=tag]').click()
  await page.getByTestId('random-insert').click()
  const rnd = page.getByTestId('section').filter({ has: page.getByTestId('random-head') })
  await expect(rnd).toHaveCount(1)
  await rnd.locator('.section-head').click({ position: { x: 200, y: 8 } })
  await page.getByTestId('scope-add-source').click()
  await expect(page.getByTestId('gacha-add-category')).toBeVisible()
  expect(await overlay()).toEqual({ bg: want, blur: 'none' })
})

