test('画师库、模板管理、百科页头那一行的控件一样高（28）、上下居中对齐', async ({ page }) => {
  const boxes = (sels: string[]) =>
    page.evaluate((sels) => sels.map((s) => {
      const r = document.querySelector(s)!.getBoundingClientRect()
      return { s, h: Math.round(r.height), cy: Math.round(r.y + r.height / 2) }
    }), sels)
  const same = (b: { s: string; h: number; cy: number }[]) => {
    for (const x of b) expect(x.h, x.s).toBe(28)
    expect(Math.max(...b.map((x) => x.cy)) - Math.min(...b.map((x) => x.cy))).toBeLessThanOrEqual(1)
  }
  await openArtists(page)
  same(await boxes(['[data-slot=tabs-list]:has([data-testid=artist-filter-all])', ':has(> [data-testid=artist-sort])', '[data-testid=artist-search]']))
  await page.getByTestId('page-library').click()
  await page.getByTestId('lib-search').waitFor()
  same(await boxes(['[data-slot=tabs-list]:has([data-testid=lib-view-list])', '[data-testid=lib-search]']))
  await page.getByTestId('page-discover').click()
  await page.getByTestId('discover-search').waitFor()
  same(await boxes(['[data-testid=discover-search]']))
})

test('编辑器两侧栏收起 / 展开是 200ms 的列宽过渡，栏里的内容不跟着挤', async ({ page }) => {
  const grid = page.getByTestId('editor-grid')
  const t = await grid.evaluate((el) => { const s = getComputedStyle(el); return { p: s.transitionProperty, d: s.transitionDuration } })
  expect(t.p).toContain('grid-template-columns')
  expect(t.d).toContain('0.2s')
  const frames = (testId: string) =>
    page.evaluate(async (testId) => {
      const col = document.querySelector('.editor-assistant')!
      ;(document.querySelector(`[data-testid=${testId}]`) as HTMLElement).click()
      const out: { col: number; box: number }[] = []
      const t0 = performance.now()
      while (performance.now() - t0 < 320) {
        await new Promise((r) => requestAnimationFrame(r))
        const box = document.querySelector('[data-testid=template-filter]')?.parentElement?.getBoundingClientRect().width ?? -1
        out.push({ col: Math.round(col.getBoundingClientRect().width), box: Math.round(box) })
      }
      return out
    }, testId)
  const a0 = Math.round((await page.locator('.editor-assistant').boundingBox())!.width)
  const w0 = Math.round((await page.getByTestId('template-filter').locator('..').boundingBox())!.width)
  const shut = await frames('assist-collapse')
  expect(shut.some((f) => f.col > 40 && f.col < a0 - 20), JSON.stringify(shut)).toBe(true)
  expect(shut.at(-1)!.col).toBe(30)
  const open = await frames('assist-rail')
  const mid = open.filter((f) => f.col > 40 && f.col < a0 - 20)
  expect(mid.length, JSON.stringify(open)).toBeGreaterThan(0)
  for (const f of mid) expect(Math.abs(f.box - w0)).toBeLessThanOrEqual(1)
  expect(open.at(-1)!.col).toBe(a0)
})

test('模板库、新标签页、画师库的搜索框长得一样（高、圆角、描边、底色、聚焦一圈）', async ({ page }) => {
  const frame = (l: Locator) => l.evaluateHandle((el) => (getComputedStyle(el).borderTopWidth === '0px' ? el.parentElement! : el))
  const look = async (l: Locator) =>
    (await frame(l)).evaluate((el) => {
      const s = getComputedStyle(el as Element)
      return { h: s.height, r: s.borderTopLeftRadius, b: `${s.borderTopWidth} ${s.borderTopStyle} ${s.borderTopColor}`, bg: s.backgroundColor }
    })
  const ring = async (l: Locator) => {
    await l.focus()
    await page.waitForTimeout(250)
    return (await frame(l)).evaluate((el) => { const s = getComputedStyle(el as Element); return `${s.boxShadow} | ${s.borderTopColor}` })
  }
  const lib = page.getByTestId('template-filter')
  const a = await look(lib)
  const ra = await ring(lib)
  await page.keyboard.press('Escape')
  await page.getByTestId('new-tab').click()
  const start = page.getByTestId('start-search')
  await start.evaluate((el) => (el as HTMLInputElement).blur())
  await page.waitForTimeout(400)
  expect(await look(start)).toEqual(a)
  expect(await ring(start)).toBe(ra)
  await openArtists(page)
  const art = page.getByTestId('artist-search')
  await art.evaluate((el) => (el as HTMLInputElement).blur())
  await page.waitForTimeout(400)
  expect(await look(art)).toEqual(a)
  expect(await ring(art)).toBe(ra)
})

